tool_calls:
cd /home/eval/pkgs && mkdir -p bin build && cat > bin/order <<'EOF'
#!/usr/bin/env bash
# Kahn's algorithm, with a min-heap of byte-sorted package ranks.
set -euo pipefail
export LC_ALL=C
if [[ $# -ne 1 ]]; then
    printf 'usage: %s dependency-file\n' "$0" >&2
    exit 2
fi
input=$1
[[ $input == /* ]] || input=./$input
names=$(mktemp)
trap 'rm -f -- "$names"' EXIT

# Include both declared packages and dependency-only packages.
awk '
function trim(s) { sub(/^[ \t\r]+/, "", s); sub(/[ \t\r]+$/, "", s); return s }
{
    sub(/#.*/, "")
    if (trim($0) == "") next
    colon = index($0, ":")
    print trim(substr($0, 1, colon - 1))
    rest = trim(substr($0, colon + 1))
    if (rest != "") {
        n = split(rest, deps, /[ \t\r]+/)
        for (i = 1; i <= n; i++) print deps[i]
    }
}' "$input" | sort -u > "$names"

awk '
function trim(s) { sub(/^[ \t\r]+/, "", s); sub(/[ \t\r]+$/, "", s); return s }
function push(v, i, p) {
    i = ++size
    while (i > 1) {
        p = int(i / 2)
        if (heap[p] <= v) break
        heap[i] = heap[p]
        i = p
    }
    heap[i] = v
}
function pop(    result, v, i, c) {
    result = heap[1]
    v = heap[size]
    delete heap[size--]
    if (size) {
        i = 1
        while (2 * i <= size) {
            c = 2 * i
            if (c < size && heap[c + 1] < heap[c]) c++
            if (v <= heap[c]) break
            heap[i] = heap[c]
            i = c
        }
        heap[i] = v
    }
    return result
}
FILENAME == ARGV[1] {
    name[++count] = $0
    rank[$0] = count
    next
}
{
    sub(/#.*/, "")
    if (trim($0) == "") next
    colon = index($0, ":")
    package = rank[trim(substr($0, 1, colon - 1))]
    rest = trim(substr($0, colon + 1))
    if (rest == "") next
    n = split(rest, deps, /[ \t\r]+/)
    for (i = 1; i <= n; i++) {
        dependency = rank[deps[i]]
        key = dependency SUBSEP package
        if (key in seen) continue
        seen[key] = 1
        degree[package]++
        target[++edges] = package
        link[edges] = head[dependency]
        head[dependency] = edges
    }
}
END {
    for (i = 1; i <= count; i++) if (!degree[i]) push(i)
    while (size) {
        v = pop()
        print name[v]
        emitted[v] = 1
        total++
        for (e = head[v]; e; e = link[e]) {
            w = target[e]
            if (--degree[w] == 0) push(w)
        }
    }
    if (total < count) {
        message = "cycle:"
        for (i = 1; i <= count; i++)
            if (!emitted[i]) message = message " " name[i]
        print message > "/dev/stderr"
        exit 1
    }
}' "$names" "$input"
EOF
chmod +x bin/order
./bin/order deps.txt > build/order.txt
./bin/order deps-big.txt > build/big-order.txt
./bin/order deps-cycle.txt > build/cycle-order.txt 2> build/cycle.txt
rc=$?
printf '%s\n' "$rc" > build/cycle.rc
printf '\n--- Outputs ---\n'
for f in build/order.txt build/big-order.txt build/cycle-order.txt build/cycle.txt build/cycle.rc; do printf '\n%s\n' "$f"; cat "$f"; done

